import type {
  CarouselEffect,
  CarouselItem,
  CarouselPose,
  CarouselSettings,
  CarouselTheme,
} from './types';

export const CAROUSEL_DEFAULT_ITEMS: CarouselItem[] = [
  {
    id: 1,
    title: 'Swipe with momentum',
    description: 'Fling the cards and they glide into place.',
    icon: 'lucide:move-horizontal',
  },
  {
    id: 2,
    title: 'Autoplay with a timer',
    description: 'The indicator fills up so people know what comes next.',
    icon: 'lucide:timer',
  },
  {
    id: 3,
    title: 'Five transitions',
    description: 'Tilt, slide, scale, fade or turn the cards like a cube.',
    icon: 'lucide:layers',
  },
  {
    id: 4,
    title: 'Keyboard friendly',
    description: 'Arrow keys, Home and End move between the cards.',
    icon: 'lucide:command',
  },
  {
    id: 5,
    title: 'Bring any content',
    description: 'Pass text, images or your own components as cards.',
    icon: 'lucide:image',
  },
];

export const CAROUSEL_THEMES: Record<CarouselTheme, Record<string, string>> = {
  dark: {
    '--carousel-frame': 'rgba(38, 35, 46, 0.66)',
    '--carousel-frame-edge': 'rgba(255, 255, 255, 0.08)',
    '--carousel-frame-highlight': 'rgba(255, 255, 255, 0.07)',
    '--carousel-frame-shadow':
      '0 22px 44px -20px rgba(0, 0, 0, 0.8), 0 6px 16px -8px rgba(0, 0, 0, 0.5)',
    '--carousel-tile': 'linear-gradient(180deg, #3a3644 0%, #27242f 100%)',
    '--carousel-tile-edge': 'rgba(255, 255, 255, 0.07)',
    '--carousel-tile-highlight': 'rgba(255, 255, 255, 0.12)',
    '--carousel-tile-shadow': '0 4px 10px -4px rgba(0, 0, 0, 0.7)',
    '--carousel-ink': '#f4f4f5',
    '--carousel-muted': 'rgba(244, 244, 245, 0.6)',
    '--carousel-faint': 'rgba(255, 255, 255, 0.22)',
    '--carousel-soft': 'rgba(255, 255, 255, 0.42)',
    '--carousel-badge': 'rgba(255, 255, 255, 0.08)',
    '--carousel-hover': 'brightness(1.12)',
    '--carousel-press': 'brightness(0.8)',
  },
  light: {
    '--carousel-frame': 'rgba(240, 240, 243, 0.8)',
    '--carousel-frame-edge': 'rgba(24, 24, 27, 0.07)',
    '--carousel-frame-highlight': 'rgba(255, 255, 255, 0.95)',
    '--carousel-frame-shadow':
      '0 22px 44px -22px rgba(24, 24, 27, 0.3), 0 6px 16px -10px rgba(24, 24, 27, 0.16)',
    '--carousel-tile': 'linear-gradient(180deg, #ffffff 0%, #f6f6f8 100%)',
    '--carousel-tile-edge': 'rgba(24, 24, 27, 0.08)',
    '--carousel-tile-highlight': 'rgba(255, 255, 255, 1)',
    '--carousel-tile-shadow': '0 4px 10px -5px rgba(24, 24, 27, 0.25)',
    '--carousel-ink': '#27272a',
    '--carousel-muted': 'rgba(39, 39, 42, 0.6)',
    '--carousel-faint': 'rgba(24, 24, 27, 0.16)',
    '--carousel-soft': 'rgba(24, 24, 27, 0.34)',
    '--carousel-badge': 'rgba(24, 24, 27, 0.05)',
    '--carousel-hover': 'brightness(0.97)',
    '--carousel-press': 'brightness(0.92)',
  },
};

export const CAROUSEL_EFFECTS: CarouselEffect[] = [
  'tilt',
  'slide',
  'scale',
  'fade',
  'cube',
];

export const CAROUSEL_STIFFNESS = 150;
export const CAROUSEL_DAMPING = 24;

export const clamp = (value: number, min: number, max: number): number =>
  Math.min(max, Math.max(min, value));

export const wrap = (value: number, count: number): number =>
  ((value % count) + count) % count;

export const nearest = (offset: number, count: number): number =>
  wrap(offset + count / 2, count) - count / 2;

const smootherstep = (t: number): number => t * t * t * (t * (t * 6 - 15) + 10);

/** Soft horizontal fade so cards dissolve at the edges when there is no frame. */
export function edgeMask(size: number): string {
  const stops = [0, 0.15, 0.3, 0.45, 0.6, 0.75, 0.9, 1].map((t) => [
    smootherstep(t).toFixed(3),
    (t * size).toFixed(1),
  ]);
  const left = stops.map(([alpha, x]) => `rgba(0, 0, 0, ${alpha}) ${x}px`);
  const right = [...stops]
    .reverse()
    .map(([alpha, x]) => `rgba(0, 0, 0, ${alpha}) calc(100% - ${x}px)`);
  return `linear-gradient(to right, ${[...left, ...right].join(', ')})`;
}

/** Rubber band past the first and last card. */
export function band(value: number, max: number): number {
  if (value < 0) return -0.3 * (1 - Math.exp(value / 0.55));
  if (value > max) return max + 0.3 * (1 - Math.exp((max - value) / 0.55));
  return value;
}

export function pose(
  index: number,
  position: number,
  s: CarouselSettings,
): CarouselPose {
  const offset = s.loop ? nearest(index - position, s.count) : index - position;
  const distance = Math.abs(offset);
  const near = Math.min(distance, 1);
  const result: CarouselPose = {
    transform: 'none',
    opacity: 1,
    visible: true,
    layer: 10 - Math.min(9, Math.round(distance * 2)),
    shade: 0,
    focus: 1,
  };
  if (s.mode === 'fade') {
    const half = Math.min(1, near * 2);
    result.visible = distance < 1;
    result.opacity = 1 - near * near * (3 - 2 * near);
    result.transform = `scale(${1 - 0.04 * near})`;
    result.focus = 1 - half * half * (3 - 2 * half);
    return result;
  }
  if (s.mode === 'cube') {
    const half = s.cardWidth / 2;
    const turn = Math.sin(Math.PI * (position - Math.floor(position)));
    result.visible = distance < 1;
    result.transform = `scale(${1 - 0.12 * turn}) translateZ(${-half}px) rotateY(${clamp(offset, -1, 1) * 90}deg) translateZ(${half}px)`;
    result.shade = near * s.shade;
    return result;
  }
  let x = offset * s.span;
  result.visible =
    x > -(s.inset + s.cardWidth + 2) && x < s.width + s.bleed * 2 - s.inset + 2;
  result.focus = 1 - near * near * (3 - 2 * near);
  if (s.mode === 'tilt') {
    result.visible = result.visible && distance < 1;
    result.transform = `translate3d(${x}px, 0, 0) rotateY(${-clamp(offset, -1, 1) * 90}deg)`;
  } else if (s.mode === 'scale') {
    x -= Math.sign(offset) * near * s.cardWidth * 0.06;
    result.transform = `translate3d(${x}px, 0, 0) scale(${1 - 0.12 * near})`;
    result.opacity = 1 - 0.5 * near;
  } else {
    result.transform = `translate3d(${x}px, 0, 0)`;
  }
  return result;
}

export { default as Carousel } from './Carousel.vue';
export type {
  CarouselEffect,
  CarouselEntry,
  CarouselIndicator,
  CarouselItem,
  CarouselProps,
  CarouselTheme,
} from './types';

import type { ComputedRef, Ref } from 'vue';

export type CarouselEffect = 'tilt' | 'slide' | 'scale' | 'fade' | 'cube';

export type CarouselIndicator = 'dots' | 'bars' | 'counter' | 'none';

export type CarouselTheme = 'dark' | 'light';

export interface CarouselItem {
  /** Stable key for the card. Falls back to the index. */
  id?: number | string;
  /** Photo that fills the card. */
  image?: string;
  /** Alt text for the photo. */
  alt?: string;
  /** Iconify icon name shown in the badge, e.g. `lucide:timer`. */
  icon?: string;
  title?: string;
  description?: string;
}

/** Objects get the built-in card; strings are used as image URLs. */
export type CarouselEntry = CarouselItem | string;

export interface CarouselProps {
  items?: CarouselEntry[];
  /** Width in px, or any CSS width. Never grows past its container. */
  baseWidth?: number | string;
  /** Card width divided by its height. */
  aspectRatio?: number;
  /** Space on each side of the active card where neighbours show, in px. */
  peek?: number;
  gap?: number;
  radius?: number;
  frame?: boolean;
  effect?: CarouselEffect;
  indicator?: CarouselIndicator;
  arrows?: boolean;
  autoplay?: boolean;
  autoplayDelay?: number;
  pauseOnHover?: boolean;
  loop?: boolean;
  draggable?: boolean;
  round?: boolean;
  initialIndex?: number;
  theme?: CarouselTheme;
  class?: string;
}

export interface CarouselCard extends CarouselItem {
  key: number | string;
}

export interface CarouselSettings {
  count: number;
  mode: CarouselEffect;
  width: number;
  bleed: number;
  inset: number;
  cardWidth: number;
  span: number;
  loop: boolean;
  autoplay: boolean;
  autoplayDelay: number;
  pauseOnHover: boolean;
  draggable: boolean;
  bars: boolean;
  shade: number;
}

export interface CarouselPose {
  transform: string;
  opacity: number;
  visible: boolean;
  layer: number;
  shade: number;
  focus: number;
}

export interface CarouselEngine {
  goTo: (index: number) => void;
  step: (direction: number, auto?: boolean) => void;
  sync: () => void;
}

export interface CarouselDragState {
  id: number;
  x: number;
  y: number;
  p: number;
  from: number;
  moved: boolean;
  samples: Array<[number, number]>;
}

export interface CarouselEngineOptions {
  root: Ref<HTMLElement | null>;
  viewport: Ref<HTMLElement | null>;
  settings: ComputedRef<CarouselSettings>;
  slides: Array<HTMLElement | null>;
  shades: Array<HTMLElement | null>;
  fills: Array<HTMLElement | null>;
  active: Ref<number>;
}

export interface CarouselEngineState {
  p: number;
  v: number;
  target: number;
  shown: number;
  elapsed: number;
  hovered: boolean;
  focused: boolean;
  visible: boolean;
  drag: CarouselDragState | null;
  wheeling: boolean;
  wheelTimer: number;
  suppress: boolean;
  last: number;
}

export interface CarouselControlsProps {
  count: number;
  active: number;
  indicator: CarouselIndicator;
  arrows: boolean;
  autoplay: boolean;
  loop: boolean;
  atStart: boolean;
  atEnd: boolean;
  /** Width of the controls row in px (matches the card). */
  width: number;
  /** Registers a bar fill element so the engine can drive its timer. */
  bindFill: (el: unknown, index: number) => void;
}

import { computed, watch } from 'vue';
import {
  tryOnScopeDispose,
  useDocumentVisibility,
  useEventListener,
  useIntersectionObserver,
  usePreferredReducedMotion,
  useRafFn,
} from '@vueuse/core';
import {
  CAROUSEL_DAMPING,
  CAROUSEL_STIFFNESS,
  band,
  clamp,
  nearest,
  pose,
  wrap,
} from './carousel-math';
import type {
  CarouselEngine,
  CarouselEngineOptions,
  CarouselEngineState,
  CarouselSettings,
} from './types';

/**
 * Spring-driven carousel position. Writes transforms straight to the slide
 * elements so dragging and settling never go through a Vue re-render.
 */
export function useCarouselEngine(
  options: CarouselEngineOptions,
): CarouselEngine {
  const { root, viewport, settings, slides, shades, fills, active } = options;
  const reducedMotion = usePreferredReducedMotion();
  const reduce = computed(() => reducedMotion.value === 'reduce');
  const documentVisibility = useDocumentVisibility();

  const start = active.value;
  const state: CarouselEngineState = {
    p: start,
    v: 0,
    target: start,
    shown: start,
    elapsed: 0,
    hovered: false,
    focused: false,
    visible: true,
    drag: null,
    wheeling: false,
    wheelTimer: 0,
    suppress: false,
    last: 0,
  };

  const unit = (s: CarouselSettings): number =>
    s.mode === 'fade' || s.mode === 'cube' ? s.cardWidth : s.span;
  const limit = (s: CarouselSettings, value: number): number =>
    s.loop ? value : clamp(value, 0, s.count - 1);

  function apply(): void {
    const s = settings.value;
    for (let i = 0; i < s.count; i++) {
      const slide = slides[i];
      if (!slide) continue;
      const next = pose(i, state.p, s);
      slide.style.transform = next.transform;
      slide.style.opacity = String(next.opacity);
      slide.style.visibility = next.visible ? 'visible' : 'hidden';
      slide.style.zIndex = String(next.layer);
      slide.style.setProperty('--carousel-focus', String(next.focus));
      const shade = shades[i];
      if (shade) shade.style.opacity = String(next.shade);
    }
    if (!s.bars) return;
    const progress = s.autoplay
      ? clamp(state.elapsed / s.autoplayDelay, 0, 1)
      : 1;
    for (let i = 0; i < s.count; i++) {
      const fill = fills[i];
      if (!fill) continue;
      const scale = i < state.shown ? 1 : i === state.shown ? progress : 0;
      fill.style.transform = `scaleX(${scale})`;
    }
  }

  function announce(): void {
    const s = settings.value;
    if (!s.count) return;
    const rounded = Math.round(state.target);
    const index = s.loop
      ? wrap(rounded, s.count)
      : clamp(rounded, 0, s.count - 1);
    if (index === state.shown) return;
    state.shown = index;
    active.value = index;
  }

  function paused(s: CarouselSettings): boolean {
    return (
      (s.pauseOnHover && state.hovered) ||
      state.focused ||
      Boolean(state.drag) ||
      state.wheeling ||
      !state.visible ||
      documentVisibility.value === 'hidden'
    );
  }

  const { pause, resume, isActive } = useRafFn(
    ({ timestamp }) => {
      const s = settings.value;
      const dt = state.last
        ? Math.min(0.05, (timestamp - state.last) / 1000)
        : 1 / 60;
      state.last = timestamp;
      let busy = false;
      if (!state.drag?.moved && !state.wheeling) {
        if (reduce.value) {
          state.p = state.target;
          state.v = 0;
        } else {
          const steps = Math.ceil(dt * 240);
          const h = dt / steps;
          for (let k = 0; k < steps; k++) {
            state.v +=
              (CAROUSEL_STIFFNESS * (state.target - state.p) -
                CAROUSEL_DAMPING * state.v) *
              h;
            state.p += state.v * h;
          }
          if (
            Math.abs(state.target - state.p) < 0.0004 &&
            Math.abs(state.v) < 0.004
          ) {
            state.p = state.target;
            state.v = 0;
          } else {
            busy = true;
          }
        }
        if (!busy && s.loop && s.count) {
          state.target = wrap(Math.round(state.target), s.count);
          state.p = state.target;
        }
      }
      if (s.autoplay && !paused(s)) {
        state.elapsed += dt * 1000;
        if (state.elapsed >= s.autoplayDelay) step(1, true);
        busy = true;
      }
      apply();
      if (!busy) {
        state.last = 0;
        pause();
      }
    },
    { immediate: false },
  );

  function wake(): void {
    if (!isActive.value) resume();
  }

  function moveTo(target: number): void {
    state.target = target;
    state.elapsed = 0;
    announce();
    apply();
    wake();
  }

  function step(direction: number, auto = false): void {
    const s = settings.value;
    if (s.count < 2) return;
    let next = Math.round(state.target) + direction;
    if (!s.loop) {
      if (auto && next > s.count - 1) next = 0;
      next = clamp(next, 0, s.count - 1);
    }
    moveTo(next);
  }

  function goTo(index: number): void {
    const s = settings.value;
    if (!s.count) return;
    const goal = clamp(Math.round(index), 0, s.count - 1);
    const current = Math.round(state.target);
    moveTo(
      s.loop ? current + nearest(goal - wrap(current, s.count), s.count) : goal,
    );
  }

  function sync(): void {
    const s = settings.value;
    if (!s.loop && s.count) {
      state.target = clamp(Math.round(state.target), 0, s.count - 1);
      state.p = clamp(state.p, -0.3, s.count - 0.7);
    }
    announce();
    apply();
    wake();
  }

  useEventListener(viewport, 'pointerdown', (event: PointerEvent) => {
    const s = settings.value;
    if (!s.draggable || (event.pointerType === 'mouse' && event.button !== 0))
      return;
    state.drag = {
      id: event.pointerId,
      x: event.clientX,
      y: event.clientY,
      p: state.p,
      from: 0,
      moved: false,
      samples: [],
    };
  });

  useEventListener(viewport, 'pointermove', (event: PointerEvent) => {
    const drag = state.drag;
    const el = viewport.value;
    if (!drag || !el || event.pointerId !== drag.id) return;
    const s = settings.value;
    if (!drag.moved) {
      const dx = event.clientX - drag.x;
      const dy = event.clientY - drag.y;
      if (Math.abs(dx) < 6 && Math.abs(dy) < 6) return;
      if (Math.abs(dy) > Math.abs(dx)) {
        state.drag = null;
        return;
      }
      drag.moved = true;
      drag.x = event.clientX;
      drag.p = state.p;
      drag.from = Math.round(state.target);
      el.setPointerCapture(event.pointerId);
      el.dataset.dragging = 'true';
    }
    const raw = drag.p - (event.clientX - drag.x) / unit(s);
    state.p = s.loop ? raw : band(raw, s.count - 1);
    state.v = 0;
    state.target = Math.round(limit(s, state.p));
    drag.samples.push([event.timeStamp, event.clientX]);
    if (drag.samples.length > 8) drag.samples.shift();
    announce();
    apply();
  });

  function onPointerUp(event: PointerEvent): void {
    const drag = state.drag;
    if (!drag || event.pointerId !== drag.id) return;
    state.drag = null;
    if (viewport.value) delete viewport.value.dataset.dragging;
    if (!drag.moved) {
      wake();
      return;
    }
    state.suppress = true;
    window.setTimeout(() => {
      state.suppress = false;
    }, 0);
    const s = settings.value;
    const sample = drag.samples.find(
      ([time]) => event.timeStamp - time < 90,
    ) ?? [event.timeStamp, event.clientX];
    const elapsed = Math.max(16, event.timeStamp - sample[0]);
    const velocity = clamp(
      ((sample[1] - event.clientX) / elapsed) * (1000 / unit(s)),
      -12,
      12,
    );
    const travelled = state.p - drag.from;
    let target = Math.round(state.p + velocity * 0.2);
    if (target === drag.from) {
      if (Math.abs(velocity) > 0.8) target += Math.sign(velocity);
      else if (Math.abs(travelled) > 0.18) target += Math.sign(travelled);
    }
    if (!s.loop) target = clamp(target, 0, s.count - 1);
    const inside = s.loop || (state.p >= 0 && state.p <= s.count - 1);
    state.v = inside ? velocity : 0;
    moveTo(target);
  }

  useEventListener(viewport, ['pointerup', 'pointercancel'], onPointerUp);

  useEventListener(
    viewport,
    'click',
    (event: MouseEvent) => {
      if (!state.suppress) return;
      event.preventDefault();
      event.stopPropagation();
      state.suppress = false;
    },
    { capture: true },
  );

  useEventListener(
    viewport,
    'wheel',
    (event: WheelEvent) => {
      const s = settings.value;
      if (!s.draggable || Math.abs(event.deltaX) <= Math.abs(event.deltaY))
        return;
      event.preventDefault();
      const raw = state.p + event.deltaX / unit(s);
      state.p = s.loop ? raw : clamp(raw, -0.15, s.count - 0.85);
      state.v = 0;
      state.wheeling = true;
      state.target = Math.round(limit(s, state.p));
      announce();
      apply();
      window.clearTimeout(state.wheelTimer);
      state.wheelTimer = window.setTimeout(() => {
        state.wheeling = false;
        moveTo(Math.round(limit(settings.value, state.p)));
      }, 120);
    },
    { passive: false },
  );

  useEventListener(root, 'keydown', (event: KeyboardEvent) => {
    if (
      event.target instanceof Element &&
      event.target.closest('input, textarea, select, [contenteditable="true"]')
    )
      return;
    const s = settings.value;
    let action: (() => void) | null = null;
    if (event.key === 'ArrowRight') action = () => step(1);
    else if (event.key === 'ArrowLeft') action = () => step(-1);
    else if (event.key === 'Home') action = () => goTo(0);
    else if (event.key === 'End') action = () => goTo(s.count - 1);
    if (!action) return;
    event.preventDefault();
    action();
  });

  useEventListener(root, 'mouseenter', () => {
    state.hovered = true;
  });

  useEventListener(root, 'mouseleave', () => {
    state.hovered = false;
    wake();
  });

  useEventListener(root, 'focusin', () => {
    const el = root.value;
    try {
      state.focused = Boolean(
        el &&
        (el.matches(':focus-visible') || el.querySelector(':focus-visible')),
      );
    } catch {
      state.focused = false;
    }
  });

  useEventListener(root, 'focusout', (event: FocusEvent) => {
    const el = root.value;
    if (
      el &&
      event.relatedTarget instanceof Node &&
      el.contains(event.relatedTarget)
    )
      return;
    state.focused = false;
    wake();
  });

  useIntersectionObserver(root, (entries) => {
    state.visible = entries.some((entry) => entry.isIntersecting);
    if (state.visible) wake();
  });

  watch(documentVisibility, (visibility) => {
    if (visibility === 'hidden') return;
    state.last = 0;
    wake();
  });

  tryOnScopeDispose(() => {
    if (state.wheelTimer) window.clearTimeout(state.wheelTimer);
  });

  return { goTo, step, sync };
}
